/// <summary>
/// N.Freidenberger 09.08.24
/// </summary>
/// <summary>
/// designed from AVA
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
display AVADocuRestrictionId displayDocuRestictionId()
{
    return AVADocuRestriction::find(this.DocuRestrictionNum).Restriction;

}

/// <summary>
/// Find Record 
/// </summary>
/// <param name = "_docuRefRecId">DocuRef recid</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>AVADocuRestrictionReference record</returns>
public static AVADocuRestrictionReference find(RefRecId _docuRefRecId, boolean _forUpdate = false)
{
    AVADocuRestrictionReference lAVADocuRestrictionReference;

    lAVADocuRestrictionReference.selectForUpdate(_forUpdate);

    select lAVADocuRestrictionReference
        where lAVADocuRestrictionReference.DocuRefRecId == _docuRefRecId;

    return lAVADocuRestrictionReference;
}

/// <summary>
/// Updates or create record
/// </summary>
/// <param name = "_docuRefRecId">Docu rec id</param>
/// <param name = "_avaDocuRestrictionNum">Restriction num</param>
/// <param name = "_forUpdate"></param>
public static void updateOrCreate(RefRecId _docuRefRecId, AVADocuRestrictionNum _avaDocuRestrictionNum, boolean _forUpdate = false)
{
    AVADocuRestrictionReference lAVADocuRestrictionReference = AVADocuRestrictionReference::find(_docuRefRecId, _forUpdate);

    if(!lAVADocuRestrictionReference)
    {
        lAVADocuRestrictionReference.insert();
    }

    ttsbegin;
    lAVADocuRestrictionReference.DocuRestrictionNum = _avaDocuRestrictionNum;
    lAVADocuRestrictionReference.update();
    ttscommit;
}
